  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Modernism: A World Broken and Remade$j$, $j${"readings": [{"title": "Colossians 1 (King James Version)", "url": "/portal/bible/Colossians/1"}], "body": "The First World War, from 1914 to 1918, shattered Europe's confidence. Millions died, empires fell, and many writers felt that the old certainties could no longer be trusted. Modernism was the literary response: writers broke from traditional forms and tried new ways to show a fractured world.\n\nCommon features of Modernist writing include fragmentation (broken, disconnected pieces), free verse (poetry with no fixed rhyme or meter), allusion (a reference to another work or event), and stream of consciousness (a narrative technique that follows the unbroken flow of a character's thoughts).\n\nT. S. Eliot's poem The Waste Land, published in 1922, is a collage of voices, languages and allusions that portrays a spiritually dry modern world. William Butler Yeats, an Irish poet, wrote The Second Coming in 1919. It pictures a world coming apart, with the lines, Things fall apart; the centre cannot hold; mere anarchy is loosed upon the world. Virginia Woolf used stream of consciousness in Mrs Dalloway, published in 1925, to follow a single day through the minds of her characters.\n\nModernist works can be difficult. To read them, slow down, notice repeated images, look up allusions, and ask what feeling the form itself creates.\n\nScripture speaks to a world that seems to be falling apart. Colossians 1:17 says that by Christ all things consist, meaning that in Him they hold together.\n\nYour task: (1) Explain why World War I led to Modernism. (2) Define three Modernist techniques. (3) Compare Yeats's picture of a world falling apart with Colossians 1:17.\n\nFlorida standards: ELA.12.R.1.4, ELA.12.R.3.1, ELA.12.R.3.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.4, ELA.12.R.3.1, ELA.12.R.3.3", "script": "Welcome to the modern age. Listen, the First World War, from 1914 to 1918, shattered Europe's confidence. Millions died, empires fell, and many writers felt that the old certainties could not be trusted anymore.\n\nModernism was the literary response. Writers broke from traditional forms and tried new ways to show a fractured world. Fragmentation means broken, disconnected pieces. Free verse means poetry with no fixed rhyme or meter. Allusion means a reference to another work or event. And stream of consciousness follows the flow of a character's thoughts.\n\nNow watch this. T. S. Eliot's The Waste Land, published in 1922, is a collage of voices and allusions that portrays a spiritually dry modern world. The Irish poet William Butler Yeats wrote The Second Coming in 1919, with the lines, Things fall apart; the centre cannot hold. And Virginia Woolf used stream of consciousness in Mrs Dalloway in 1925 to follow a single day through the minds of her characters.\n\nModernist works can be hard. Slow down, notice repeated images, look up allusions, and ask what the form itself makes you feel.\n\nScripture speaks to a world that feels like it is falling apart. Colossians 1:17 says that by Christ all things consist. In Him they hold together. Your task is to explain why the war led to Modernism, define three techniques, and compare Yeats with Colossians. Take the four question check. Hold fast. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Modernism: A World Broken and Remade$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 The War Poets: Owen and Sassoon$j$, $j${"readings": [{"title": "Isaiah 2 (King James Version)", "url": "/portal/bible/Isaiah/2"}], "body": "Early in World War I, many British poets wrote noble, patriotic verse. As the war dragged on, soldiers who had seen the trenches wrote differently. Wilfred Owen and Siegfried Sassoon are the best known of these war poets. Owen was killed in action in November 1918, only one week before the armistice, at the age of 25. Most of his poems were published after his death.\n\nOwen's poem Dulce et Decorum Est describes soldiers marching, exhausted, until a gas attack. The title comes from a Latin line that means it is sweet and fitting to die for one's country. Owen calls that idea the old Lie. He uses vivid imagery, harsh sounds and a sudden shift from marching to terror to make readers feel the horror, and he addresses the reader directly, which is called apostrophe, to challenge easy praise of war.\n\nThe poem is an example of irony, since the title says one thing and the poem shows another. To analyze it, note the tone at the beginning and at the end, track sound devices, and decide what Owen wants the reader to do.\n\nHonoring those who serve, and hating war, can go together. Scripture looks forward to a day of peace. Isaiah 2:4 says they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up sword against nation, neither shall they learn war any more.\n\nYour task: (1) Explain why the war poets wrote differently from earlier poets. (2) Identify two techniques in Owen's poem. (3) Explain the meaning of the title and connect the poem to Isaiah 2:4.\n\nFlorida standards: ELA.12.R.1.4, ELA.12.R.3.1, ELA.12.R.2.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.4, ELA.12.R.3.1, ELA.12.R.2.2", "script": "Now we turn to a sober subject. Listen, early in the First World War, many British poets wrote noble, patriotic verse. As the war dragged on, the soldiers who had seen the trenches wrote differently.\n\nWilfred Owen and Siegfried Sassoon are the best known of the war poets. Owen was killed in November 1918, only one week before the armistice, at the age of twenty five. Most of his poems were published after his death.\n\nNow watch this. Owen's poem Dulce et Decorum Est describes exhausted soldiers marching until a gas attack. The Latin title means it is sweet and fitting to die for one's country, and Owen calls that idea the old Lie. He uses vivid imagery, harsh sounds and a sudden shift from marching to terror, and he speaks directly to the reader, challenging easy praise of war.\n\nThat is irony. The title says one thing, and the poem shows another. To analyze it, compare the tone at the beginning and the end, track the sound devices, and ask what Owen wants the reader to do.\n\nWe can honor those who serve and still hate war. Isaiah 2:4 says they shall beat their swords into plowshares. Your task is to explain why the war poets wrote differently, identify two techniques, and explain the title. Take the four question check. Remember with respect. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 The War Poets: Owen and Sassoon$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Faith and Freedom of Mind: C. S. Lewis and George Orwell$j$, $j${"readings": [{"title": "John 8 (King James Version)", "url": "/portal/bible/John/8"}], "body": "Two twentieth century British writers used imagination to defend truth. C. S. Lewis, a professor at Oxford and later Cambridge, was once an atheist who became a Christian. He wrote The Screwtape Letters in 1942, a satire in the form of letters from a senior devil to a junior devil, which shows how temptation works in everyday life. His BBC radio talks during World War II became Mere Christianity, and from 1950 to 1956 he published the seven Chronicles of Narnia, fantasy stories with a Christlike lion, Aslan.\n\nGeorge Orwell was a journalist and novelist who hated tyranny. In Animal Farm, published in 1945, farm animals overthrow their master and then are ruled by pigs who bend the rules for themselves, a political allegory about the Russian Revolution. The slogan, All animals are equal, but some animals are more equal than others, shows how language can be twisted. In Nineteen Eighty Four, published in 1949, a government controls speech and even thought through Newspeak, and Orwell warns that whoever controls language and truth controls people.\n\nCompare the two. Both use genre, Lewis satire and fantasy, Orwell allegory and dystopia, a story of a harsh, controlled society. Both defend truth against deception.\n\nJesus said in John 8:32, Ye shall know the truth, and the truth shall make you free.\n\nYour task: (1) Define allegory, satire and dystopia using these works. (2) Explain how Orwell shows language being misused. (3) Connect one idea from Lewis or Orwell to John 8:32.\n\nFlorida standards: ELA.12.R.1.2, ELA.12.R.2.2, ELA.12.R.3.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.2, ELA.12.R.2.2, ELA.12.R.3.4", "script": "Welcome back. Listen, two British writers of the twentieth century used imagination to defend truth. Let's meet them.\n\nC. S. Lewis was a professor at Oxford and later Cambridge. He was once an atheist, and he became a Christian. In 1942 he wrote The Screwtape Letters, a satire in the form of letters from a senior devil to a junior devil, showing how temptation works in everyday life. His radio talks during the war became Mere Christianity. And from 1950 to 1956 he wrote the seven Chronicles of Narnia, with a Christlike lion named Aslan.\n\nNow watch this. George Orwell was a journalist who hated tyranny. In Animal Farm, published in 1945, the animals overthrow their master, and then pigs rule and bend the rules for themselves. It is a political allegory. The slogan, All animals are equal, but some animals are more equal than others, shows how language can be twisted. In Nineteen Eighty Four, published in 1949, a government controls speech and thought through Newspeak. Whoever controls language and truth controls people.\n\nBoth writers defend truth against deception. Jesus said in John 8:32, Ye shall know the truth, and the truth shall make you free.\n\nYour task is to define allegory, satire and dystopia, explain how Orwell shows misuse of language, and connect an idea to Scripture. Take the four question check. Love the truth. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Faith and Freedom of Mind: C. S. Lewis and George Orwell$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Voices from Around the World: Chinua Achebe$j$, $j${"readings": [{"title": "Acts 17 (King James Version)", "url": "/portal/bible/Acts/17"}], "body": "English is now spoken and written around the world, and some of the finest writers in English come from places once ruled by Britain. Postcolonial literature is writing from nations that were colonies, often showing how people experienced colonial rule and speaking from their own point of view.\n\nChinua Achebe, a Nigerian novelist, published Things Fall Apart in 1958. The title comes from the poem by Yeats you studied, The Second Coming. The novel is set in an Igbo village in the late 1800s. Its hero, Okonkwo, is a strong, proud farmer and wrestler who fears weakness. Achebe first shows village life with its customs, proverbs, justice and festivals, a rich society with its own strengths and flaws. Then European missionaries and a colonial government arrive, and the community is divided. Okonkwo's pride and fear lead to his tragic end.\n\nA reader should notice point of view. Earlier British novels often described Africa from the outside. Achebe tells the story from the inside, with African voices. He uses Igbo proverbs, which he calls the palm oil with which words are eaten. This is an example of how culture shapes style.\n\nThe Bible teaches the equal worth of every people. Acts 17:26 says that God hath made of one blood all nations of men for to dwell on all the face of the earth.\n\nYour task: (1) Define postcolonial literature. (2) Explain why Achebe's point of view matters. (3) Describe Okonkwo as a tragic hero and connect the story to Acts 17:26.\n\nFlorida standards: ELA.12.R.3.3, ELA.12.R.3.4, ELA.12.R.1.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.3.3, ELA.12.R.3.4, ELA.12.R.1.2", "script": "Now we widen the circle. Listen, English is spoken and written all over the world today, and some of its finest writers come from places that were once ruled by Britain. We call this postcolonial literature, writing from former colonies that shows how people experienced colonial rule from their own point of view.\n\nChinua Achebe is a Nigerian novelist. His book Things Fall Apart was published in 1958, and the title comes from the Yeats poem we studied, The Second Coming.\n\nNow watch this. The story is set in an Igbo village in the late 1800s. Okonkwo is a strong, proud farmer and wrestler who fears weakness. Achebe first shows village life with its customs, proverbs, justice and festivals, a rich society with strengths and flaws. Then European missionaries and a colonial government arrive, and the community is divided. Okonkwo's pride and fear lead to a tragic end. He is a tragic hero, just like Macbeth.\n\nLook at the point of view. Earlier British novels often described Africa from the outside. Achebe tells the story from the inside, with Igbo proverbs, which he called the palm oil with which words are eaten.\n\nActs 17:26 says God hath made of one blood all nations of men. Your task is to define postcolonial literature, explain why Achebe's point of view matters, and describe Okonkwo as a tragic hero. Take the four question check. Listen to every voice. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Voices from Around the World: Chinua Achebe$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: The Modern Age and Voices of the World$j$, $j${"prompt": "Write a comparison essay of at least 350 words. Use complete sentences and label each part. Proverbs 2:6 says, For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding.\n\nPart 1: Choose two works or authors from this unit (for example Yeats and Owen, Orwell and Lewis, Eliot and Achebe). State a thesis that compares them.\nPart 2: Explain the historical background that shaped each work, such as World War I, totalitarianism or colonial rule.\nPart 3: Compare at least two techniques or forms, such as free verse, irony, allegory, satire, stream of consciousness or point of view, with a brief quotation or example for each.\nPart 4: Compare the themes and say which work you find more convincing and why.\nPart 5: Connect your comparison to a passage of Scripture and write a concluding paragraph.", "rubric": "100 points. Part 1, thesis: 15 points. Part 2, background: 15 points. Part 3, techniques: 25 points. Part 4, themes and judgment: 20 points. Part 5, Scripture and conclusion: 15 points. Conventions: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: The Modern Age and Voices of the World$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: War, Truth and Every Nation$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains why you think writers turn to new forms during times of great change, (2) tells what you learned about the cost of war from Owen or about the danger of misused language from Orwell, (3) describes why it matters to hear stories from people of other nations in their own words, and (4) connects your answer to Micah 4:3, which says, Nation shall not lift up a sword against nation, neither shall they learn war any more. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can we tell when language is being used to hide the truth? Keep your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: War, Truth and Every Nation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Modernism: A World Broken and Remade$j$, $j${"questions": [{"q": "Modernism arose largely in response to:", "options": ["The invention of printing", "The Renaissance", "The Norman Conquest", "World War I"]}, {"q": "Stream of consciousness is a technique that:", "options": ["Describes only landscapes", "Uses strict rhyme", "Lists facts", "Follows the flow of a character's thoughts"]}, {"q": "An allusion is:", "options": ["A type of rhyme", "A definition", "A reference to another work or event", "A stage direction"]}, {"q": "Yeats's The Second Coming pictures a world that is:", "options": ["At peace", "Falling apart", "Growing rich", "Asleep"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Modernism: A World Broken and Remade$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,2,1}'::int[], array[$j$The war shattered old certainties.$j$,$j$Virginia Woolf used it in Mrs Dalloway.$j$,$j$Eliot filled The Waste Land with allusions.$j$,$j$Things fall apart; the centre cannot hold.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Modernism: A World Broken and Remade$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: The War Poets: Owen and Sassoon$j$, $j${"questions": [{"q": "Wilfred Owen was killed:", "options": ["At Hastings", "One week before the armistice in 1918", "In 1945", "In 1066"]}, {"q": "Dulce et Decorum Est means roughly:", "options": ["Peace be with you", "Praise the king", "It is sweet and fitting to die for one's country", "Long live the queen"]}, {"q": "The poem uses irony because:", "options": ["It is short", "It is about a king", "The title says one thing and the poem shows another", "It rhymes"]}, {"q": "Isaiah 2:4 looks forward to a time when:", "options": ["Swords are beaten into plowshares", "Kings fight", "Armies grow", "Wars are won"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The War Poets: Owen and Sassoon$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,0}'::int[], array[$j$He died on November 4, 1918.$j$,$j$Owen calls the idea the old Lie.$j$,$j$The poem challenges the Latin claim.$j$,$j$It is a vision of lasting peace.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The War Poets: Owen and Sassoon$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Faith and Freedom of Mind: C. S. Lewis and George Orwell$j$, $j${"questions": [{"q": "The Screwtape Letters is:", "options": ["A sonnet sequence", "An epic poem", "A play", "A satire in letters from a senior devil to a junior devil"]}, {"q": "Animal Farm is best described as:", "options": ["A dictionary", "A romance", "A sonnet", "A political allegory"]}, {"q": "Newspeak in Nineteen Eighty Four shows:", "options": ["A kind of music", "How a government can control thought through language", "A new poem", "A school subject"]}, {"q": "John 8:32 says the truth will:", "options": ["Make you free", "Change daily", "Be hidden", "Divide families"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Faith and Freedom of Mind: C. S. Lewis and George Orwell$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,1,0}'::int[], array[$j$Lewis published it in 1942.$j$,$j$Characters and events stand for real history.$j$,$j$Language shapes thought.$j$,$j$Ye shall know the truth, and the truth shall make you free.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Faith and Freedom of Mind: C. S. Lewis and George Orwell$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Voices from Around the World: Chinua Achebe$j$, $j${"questions": [{"q": "Things Fall Apart was written by:", "options": ["Mary Shelley", "George Orwell", "Chinua Achebe", "Charles Dickens"]}, {"q": "The title Things Fall Apart comes from a poem by:", "options": ["Alexander Pope", "W. B. Yeats", "John Milton", "Robert Browning"]}, {"q": "Postcolonial literature is writing:", "options": ["About sonnets only", "From former colonies, from their own point of view", "In Old English", "About medieval knights"]}, {"q": "Acts 17:26 teaches that:", "options": ["Nations are enemies by nature", "Only one nation matters", "Languages are unimportant", "God made all nations of one blood"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Voices from Around the World: Chinua Achebe$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,3}'::int[], array[$j$Achebe published it in 1958.$j$,$j$It comes from The Second Coming.$j$,$j$It gives voice to people who lived under colonial rule.$j$,$j$All people share equal worth before God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Voices from Around the World: Chinua Achebe$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: The Modern Age and Voices of the World$j$, $j${"questions": [{"q": "Modernist writers often used:", "options": ["Only strict rhyme", "Latin only", "Fragmentation and free verse", "No imagery"]}, {"q": "T. S. Eliot wrote:", "options": ["Animal Farm", "The Waste Land", "Everyman", "Beowulf"]}, {"q": "Wilfred Owen's poem challenges:", "options": ["The idea of school", "The idea that dying in war is glorious", "The idea of poetry", "The idea of peace"]}, {"q": "Animal Farm is an allegory of:", "options": ["The Russian Revolution", "The Trojan War", "The Reformation", "The Norman Conquest"]}, {"q": "The Screwtape Letters is:", "options": ["A diary", "A satire by C. S. Lewis", "A poem by Milton", "A play by Shakespeare"]}, {"q": "Stream of consciousness follows:", "options": ["A character's flow of thoughts", "A list of dates", "A stage direction", "A rhyme scheme"]}, {"q": "Achebe's Things Fall Apart is set in:", "options": ["A London office", "An Igbo village in Nigeria", "A Scottish moor", "A French castle"]}, {"q": "Postcolonial literature often emphasizes:", "options": ["The point of view of formerly colonized peoples", "Greek gods", "Sea voyages only", "Medieval knights"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Modern Age and Voices of the World$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,0,1,0,1,0}'::int[], array[$j$They broke from traditional forms.$j$,$j$Eliot published it in 1922.$j$,$j$He calls it the old Lie.$j$,$j$Orwell used farm animals to represent political events.$j$,$j$It was published in 1942.$j$,$j$Woolf used it in Mrs Dalloway.$j$,$j$The novel is set in the late 1800s.$j$,$j$Writers tell the story from the inside.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Modern Age and Voices of the World$j$ on conflict (item_id) do nothing;
